{
    "name": "blend-ui-mcp",
    "version": "2.0.2",
    "description": "MCP server for Blend design system - provides tools for generating React components, documentation and design tokens",
    "type": "module",
    "bin": {
        "blend-mcp": "./index.js"
    },
    "files": [
        "index.js",
        "validators.js",
        "manifest.json",
        "README.md"
    ],
    "scripts": {
        "generate-manifest": "node generateManifest.js",
        "prepublishOnly": "node generateManifest.js",
        "build": "node generateManifest.js && node -e \"import('fs').then(fs => fs.default.chmodSync('index.js', '755'))\"",
        "watch": "echo 'No watch needed for JavaScript files'",
        "inspector": "npx @modelcontextprotocol/inspector index.js",
        "test": "node test.js"
    },
    "dependencies": {
        "@modelcontextprotocol/sdk": "^1.10.0"
    },
    "devDependencies": {
        "@types/node": "^20.11.24",
        "ts-morph": "^23.0.0"
    },
    "keywords": [
        "mcp",
        "model-context-protocol",
        "blend",
        "design-system",
        "react",
        "components"
    ],
    "author": "Juspay",
    "license": "MIT",
    "repository": {
        "type": "git",
        "url": "git+https://github.com/juspay/blend-design-system.git",
        "directory": "packages/mcp"
    },
    "bugs": {
        "url": "https://github.com/juspay/blend-design-system/issues"
    },
    "homepage": "https://github.com/juspay/blend-design-system/tree/main/packages/mcp#readme",
    "engines": {
        "node": ">=18.0.0"
    }
}

-- Add google_id column to existing users table
ALTER TABLE users ALTER COLUMN firebase_uid DROP NOT NULL;
ALTER TABLE users ADD COLUMN IF NOT EXISTS google_id VARCHAR(255);

-- Create unique index for google_id (only for non-null values)
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS users_google_id_key ON users(google_id) WHERE google_id IS NOT NULL;

-- Verify changes
\d users

import '@testing-library/jest-dom'
import 'jest-styled-components'
import { cleanup } from '@testing-library/react'
import { afterEach, vi, beforeAll, afterAll, expect } from 'vitest'
import { toHaveNoViolations } from 'jest-axe'
import './__tests__/test-utils/jest-axe.d.ts'

vi.mock('monaco-editor/esm/vs/editor/editor.main.js', () => ({ editor: {} }))

// Extend expect with jest-axe matchers
expect.extend(toHaveNoViolations)

// Cleanup after each test
afterEach(() => {
    cleanup()
})

// Mock ResizeObserver
global.ResizeObserver = vi.fn().mockImplementation(() => ({
    observe: vi.fn(),
    unobserve: vi.fn(),
    disconnect: vi.fn(),
}))

// Mock window.matchMedia
Object.defineProperty(window, 'matchMedia', {
    writable: true,
    value: vi.fn().mockImplementation((query) => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(), // deprecated
        removeListener: vi.fn(), // deprecated
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
    })),
})

// Mock IntersectionObserver
global.IntersectionObserver = vi.fn().mockImplementation(() => ({
    observe: vi.fn(),
    unobserve: vi.fn(),
    disconnect: vi.fn(),
}))

// jsdom does not implement window.scrollTo; required by useScrollLock (e.g. Modal)
window.scrollTo = vi.fn()

// Mock CSS.supports for Highcharts compatibility
// Highcharts uses CSS.supports which is not available in jsdom
const mockCSSSupports = vi.fn().mockImplementation(() => true)

if (typeof global.CSS === 'undefined') {
    ;(global as unknown as { CSS: { supports: typeof mockCSSSupports } }).CSS =
        {
            supports: mockCSSSupports,
        }
} else {
    if (!CSS.supports || typeof CSS.supports !== 'function') {
        Object.defineProperty(CSS, 'supports', {
            writable: true,
            configurable: true,
            value: mockCSSSupports,
        })
    }
}

// Also ensure window.CSS exists
if (typeof window !== 'undefined' && typeof window.CSS === 'undefined') {
    ;(window as unknown as { CSS: { supports: typeof mockCSSSupports } }).CSS =
        {
            supports: mockCSSSupports,
        }
}

// Suppress console errors in tests unless explicitly testing them
const originalError = console.error
beforeAll(() => {
    console.error = (...args: unknown[]) => {
        if (
            typeof args[0] === 'string' &&
            args[0].includes('Warning: ReactDOM.render')
        ) {
            return
        }
        originalError.call(console, ...args)
    }
})

afterAll(() => {
    console.error = originalError
})

#!/usr/bin/env node
/**
 * test.js — MCP server test harness (dev-only, not shipped)
 * Run: node test.js
 */

import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import { dirname } from 'path'
import { validateComponentUsage } from './validators.js'

const __filename = fileURLToPath(import.meta.url)
const __dirname = dirname(__filename)

let passed = 0
let failed = 0

function assert(condition, description, reason = '') {
    if (condition) {
        console.log(`✅ PASS: ${description}`)
        passed++
    } else {
        console.log(`❌ FAIL: ${description}${reason ? ` — ${reason}` : ''}`)
        failed++
    }
}

// ---------------------------------------------------------------------------
// Section 1: Manifest integrity
// ---------------------------------------------------------------------------
console.log('\n--- Section 1: Manifest integrity ---')

const manifestPath = path.join(__dirname, 'manifest.json')
let manifest = null

try {
    const raw = fs.readFileSync(manifestPath, 'utf-8')
    manifest = JSON.parse(raw)
    assert(true, 'manifest.json exists and is valid JSON')
} catch (err) {
    assert(false, 'manifest.json exists and is valid JSON', err.message)
    console.log('\n=== Results: 0 passed, 1 failed ===')
    console.log('Cannot continue without manifest.json')
    process.exit(1)
}

assert(
    manifest.version === '2.0.0',
    'manifest.version === "2.0.0"',
    `got "${manifest.version}"`
)

const componentKeys = Object.keys(manifest.components || {})
assert(
    componentKeys.length >= 47,
    `manifest has >= 47 components`,
    `got ${componentKeys.length}`
)

const tokenKeys = Object.keys(manifest.tokens || {})
const requiredTokenKeys = [
    'colors',
    'spacing',
    'borders',
    'shadows',
    'typography',
]
for (const key of requiredTokenKeys) {
    assert(
        tokenKeys.includes(key),
        `manifest.tokens has key "${key}"`,
        `found keys: ${tokenKeys.join(', ')}`
    )
}

let allComponentsValid = true
let invalidComponents = []
for (const [name, comp] of Object.entries(manifest.components || {})) {
    const valid =
        typeof comp.componentName === 'string' &&
        typeof comp.category === 'string' &&
        Array.isArray(comp.props) &&
        comp.enums !== null &&
        typeof comp.enums === 'object'
    if (!valid) {
        allComponentsValid = false
        invalidComponents.push(name)
    }
}
assert(
    allComponentsValid,
    'Every component has componentName, category, props (array), enums (object)',
    invalidComponents.length > 0
        ? `Invalid: ${invalidComponents.join(', ')}`
        : ''
)

const requiredComponents = [
    'Button',
    'Alert',
    'Modal',
    'Tabs',
    'Checkbox',
    'Switch',
    'Radio',
    'TextInput',
    'SingleSelect',
    'MultiSelect',
    'Accordion',
    'DataTable',
    'Avatar',
    'Breadcrumb',
    'Card',
    'Tags',
    'Tooltip',
    'Popover',
    'Drawer',
    'Snackbar',
]
for (const name of requiredComponents) {
    assert(
        name in (manifest.components || {}),
        `Component "${name}" exists in manifest`,
        `not found; available: ${componentKeys.slice(0, 5).join(', ')}...`
    )
}

// ---------------------------------------------------------------------------
// Section 2: Compound components
// ---------------------------------------------------------------------------
console.log('\n--- Section 2: Compound components ---')

const accordion = manifest.components['Accordion']
assert(
    accordion?.isCompound === true,
    'Accordion.isCompound === true',
    `got ${accordion?.isCompound}`
)
assert(
    Array.isArray(accordion?.subComponents) &&
        accordion.subComponents.includes('AccordionItem'),
    'Accordion.subComponents includes "AccordionItem"',
    `got ${JSON.stringify(accordion?.subComponents)}`
)

const radio = manifest.components['Radio']
assert(
    radio?.isCompound === true,
    'Radio.isCompound === true',
    `got ${radio?.isCompound}`
)
assert(
    Array.isArray(radio?.subComponents) &&
        radio.subComponents.includes('RadioGroup'),
    'Radio.subComponents includes "RadioGroup"',
    `got ${JSON.stringify(radio?.subComponents)}`
)

const sw = manifest.components['Switch']
assert(
    sw?.isCompound === true,
    'Switch.isCompound === true',
    `got ${sw?.isCompound}`
)
assert(
    Array.isArray(sw?.subComponents) &&
        sw.subComponents.includes('SwitchGroup'),
    'Switch.subComponents includes "SwitchGroup"',
    `got ${JSON.stringify(sw?.subComponents)}`
)

assert(
    'AccordionItem' in (manifest.components || {}),
    'AccordionItem exists as a top-level component in manifest'
)
assert(
    'RadioGroup' in (manifest.components || {}),
    'RadioGroup exists as a top-level component in manifest'
)
assert(
    'SwitchGroup' in (manifest.components || {}),
    'SwitchGroup exists as a top-level component in manifest'
)

// ---------------------------------------------------------------------------
// Section 3: Enum extraction
// ---------------------------------------------------------------------------
console.log('\n--- Section 3: Enum extraction ---')

const button = manifest.components['Button']
const buttonEnums = button?.enums || {}

assert(
    'ButtonType' in buttonEnums,
    'Button has enum ButtonType',
    `found enums: ${Object.keys(buttonEnums).join(', ')}`
)
assert(
    'ButtonSize' in buttonEnums,
    'Button has enum ButtonSize',
    `found enums: ${Object.keys(buttonEnums).join(', ')}`
)
assert(
    'ButtonSubType' in buttonEnums,
    'Button has enum ButtonSubType',
    `found enums: ${Object.keys(buttonEnums).join(', ')}`
)

const buttonTypeMembers = Object.keys(buttonEnums['ButtonType'] || {})
for (const member of ['PRIMARY', 'SECONDARY', 'DANGER', 'SUCCESS']) {
    assert(
        buttonTypeMembers.includes(member),
        `ButtonType has member "${member}"`,
        `found: ${buttonTypeMembers.join(', ')}`
    )
}

const alert = manifest.components['Alert']
const alertEnums = alert?.enums || {}
assert(
    'AlertVariant' in alertEnums,
    'Alert has enum AlertVariant',
    `found enums: ${Object.keys(alertEnums).join(', ')}`
)
assert(
    'AlertStyle' in alertEnums,
    'Alert has enum AlertStyle',
    `found enums: ${Object.keys(alertEnums).join(', ')}`
)

const tabs = manifest.components['Tabs']
const tabsEnums = tabs?.enums || {}
assert(
    'TabsVariant' in tabsEnums,
    'Tabs has enum TabsVariant',
    `found enums: ${Object.keys(tabsEnums).join(', ')}`
)
assert(
    'TabsSize' in tabsEnums,
    'Tabs has enum TabsSize',
    `found enums: ${Object.keys(tabsEnums).join(', ')}`
)

// ---------------------------------------------------------------------------
// Section 4: Meta-overrides applied
// ---------------------------------------------------------------------------
console.log('\n--- Section 4: Meta-overrides applied ---')

assert(
    typeof button?.componentDescription === 'string' &&
        button.componentDescription.length > 50,
    'Button.componentDescription contains meaningful text (>50 chars)',
    `got: "${button?.componentDescription?.slice(0, 60)}..."`
)

const buttonPropsWithContext = (button?.props || []).filter(
    (p) => typeof p.llmContext === 'string' && p.llmContext.length > 0
)
assert(
    buttonPropsWithContext.length >= 1,
    'Button props have at least one with a non-empty llmContext',
    `found ${buttonPropsWithContext.length} props with llmContext`
)

assert(
    accordion?.compositionPattern !== null &&
        accordion?.compositionPattern !== undefined &&
        typeof accordion?.compositionPattern === 'string' &&
        accordion.compositionPattern.length > 0,
    'Accordion.compositionPattern is a non-null, non-empty string',
    `got: ${JSON.stringify(accordion?.compositionPattern)}`
)

// ---------------------------------------------------------------------------
// Section 5: Validator logic
// ---------------------------------------------------------------------------
console.log('\n--- Section 5: Validator logic ---')

// Valid props → { valid: true }
const validResult = validateComponentUsage(manifest, 'Button', {
    text: 'Submit',
})
assert(
    validResult.valid === true,
    'validateComponentUsage: valid props → { valid: true }',
    `errors: ${validResult.errors.join('; ')}`
)

// Unknown prop → errors mention the unknown prop
const unknownResult = validateComponentUsage(manifest, 'Button', {
    colour: 'red',
})
assert(
    unknownResult.valid === false &&
        unknownResult.errors.some(
            (e) =>
                e.toLowerCase().includes('colour') ||
                e.toLowerCase().includes('unknown')
        ),
    'validateComponentUsage: unknown prop → errors include mention of unknown prop',
    `errors: ${unknownResult.errors.join('; ')}`
)

// Typo → "Did you mean" suggestion
const typoResult = validateComponentUsage(manifest, 'Button', {
    typ: 'primary',
})
assert(
    typoResult.valid === false &&
        typoResult.errors.some((e) => e.includes('Did you mean')),
    'validateComponentUsage: typo prop "typ" → error has "Did you mean" suggestion',
    `errors: ${typoResult.errors.join('; ')}`
)

// Unknown component → errors mention component not found
const unknownCompResult = validateComponentUsage(
    manifest,
    'NonExistentComp',
    {}
)
assert(
    unknownCompResult.valid === false &&
        unknownCompResult.errors.some(
            (e) =>
                e.toLowerCase().includes('not found') ||
                e.toLowerCase().includes('nonexistentcomp')
        ),
    'validateComponentUsage: unknown component → errors mention component not found',
    `errors: ${unknownCompResult.errors.join('; ')}`
)

// ---------------------------------------------------------------------------
// Section 6: Tabs prop count sanity check
// ---------------------------------------------------------------------------
console.log('\n--- Section 6: Tabs prop count sanity check ---')

const tabsProps = tabs?.props || []
assert(
    tabsProps.length < 50,
    `Tabs.props.length < 50 (got ${tabsProps.length}) — should be ~15 Blend-specific props, not inherited HTML props`,
    `got ${tabsProps.length}`
)

// ---------------------------------------------------------------------------
// Final results
// ---------------------------------------------------------------------------
console.log(`\n=== Results: ${passed} passed, ${failed} failed ===`)
process.exit(failed > 0 ? 1 : 0)

{
    "openapi": "3.0.3",
    "info": {
        "title": "Blend Token Studio API",
        "description": "RESTful API for managing design token branches, versions, and snapshots. Supports branch-based workflows with version control and real-time previews.",
        "version": "1.0.0",
        "contact": {
            "name": "Blend Team",
            "email": "support@blend.studio"
        },
        "license": {
            "name": "MIT",
            "url": "https://opensource.org/licenses/MIT"
        }
    },
    "externalDocs": {
        "description": "Find out more about Blend Token Studio",
        "url": "https://docs.blend.studio"
    },
    "servers": [
        {
            "url": "http://localhost:3001/api",
            "description": "Local development server"
        },
        {
            "url": "https://firestore.googleapis.com/v1/projects/{projectId}/databases/(default)/documents",
            "description": "Firestore REST API",
            "variables": {
                "projectId": {
                    "default": "dummy-project",
                    "description": "Firebase project ID"
                }
            }
        },
        {
            "url": "https://api-staging.blend.studio/api",
            "description": "Staging environment"
        },
        {
            "url": "https://api.blend.studio/api",
            "description": "Production environment"
        }
    ],
    "security": [
        {
            "bearerAuth": []
        }
    ],
    "tags": [
        {
            "name": "Branches",
            "description": "Operations for managing design token branches"
        },
        {
            "name": "Versions",
            "description": "Version control and publishing operations"
        },
        {
            "name": "Snapshots",
            "description": "Auto-save and manual snapshot management"
        },
        {
            "name": "Tokens",
            "description": "Token resolution and preview operations"
        }
    ],
    "paths": {
        "/branches": {
            "get": {
                "summary": "List all branches",
                "description": "Retrieve a paginated list of branches with optional filtering",
                "operationId": "listBranches",
                "tags": ["Branches"],
                "parameters": [
                    {
                        "name": "status",
                        "in": "query",
                        "description": "Filter branches by status",
                        "schema": {
                            "type": "string",
                            "enum": ["draft", "published", "archived"]
                        }
                    },
                    {
                        "name": "search",
                        "in": "query",
                        "description": "Search by name or branch ID",
                        "schema": {
                            "type": "string"
                        }
                    },
                    {
                        "name": "tags",
                        "in": "query",
                        "description": "Filter by tags (comma-separated)",
                        "schema": {
                            "type": "string"
                        }
                    },
                    {
                        "name": "sortBy",
                        "in": "query",
                        "description": "Sort field",
                        "schema": {
                            "type": "string",
                            "enum": [
                                "name",
                                "createdAt",
                                "updatedAt",
                                "lastPublishedAt"
                            ],
                            "default": "updatedAt"
                        }
                    },
                    {
                        "name": "sortOrder",
                        "in": "query",
                        "description": "Sort direction",
                        "schema": {
                            "type": "string",
                            "enum": ["asc", "desc"],
                            "default": "desc"
                        }
                    },
                    {
                        "name": "limit",
                        "in": "query",
                        "description": "Number of results per page",
                        "schema": {
                            "type": "integer",
                            "default": 50,
                            "minimum": 1,
                            "maximum": 100
                        }
                    },
                    {
                        "name": "cursor",
                        "in": "query",
                        "description": "Pagination cursor",
                        "schema": {
                            "type": "string"
                        }
                    }
                ],
                "responses": {
                    "200": {
                        "description": "Successfully retrieved branches",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/BranchListResponse"
                                },
                                "example": {
                                    "branches": [
                                        {
                                            "id": "hdfc/retail",
                                            "brandId": "hdfc",
                                            "name": "HDFC Retail",
                                            "slug": "retail",
                                            "status": "published",
                                            "visibility": "team",
                                            "latestVersion": "2.1.0",
                                            "publishedCount": 12,
                                            "createdAt": "2024-01-15T00:00:00Z",
                                            "updatedAt": "2024-03-20T00:00:00Z"
                                        }
                                    ],
                                    "total": 1,
                                    "hasMore": false
                                }
                            }
                        }
                    },
                    "401": {
                        "description": "Unauthorized - Invalid or missing authentication token",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/Error"
                                }
                            }
                        }
                    }
                }
            },
            "post": {
                "summary": "Create a new branch",
                "description": "Create a new design token branch with an optional parent branch for forking",
                "operationId": "createBranch",
                "tags": ["Branches"],
                "requestBody": {
                    "required": true,
                    "description": "Branch creation parameters",
                    "content": {
                        "application/json": {
                            "schema": {
                                "$ref": "#/components/schemas/CreateBranchRequest"
                            },
                            "examples": {
                                "simple": {
                                    "summary": "Simple branch creation",
                                    "value": {
                                        "brandId": "acme",
                                        "name": "Acme Brand",
                                        "slug": "brand",
                                        "description": "Main brand theme for Acme Corporation"
                                    }
                                },
                                "with-config": {
                                    "summary": "Branch with initial brand config",
                                    "value": {
                                        "brandId": "hdfc",
                                        "name": "HDFC Retail",
                                        "slug": "retail",
                                        "visibility": "team",
                                        "tags": ["banking", "retail"],
                                        "brandConfig": {
                                            "brandId": "hdfc-retail",
                                            "name": "HDFC Retail",
                                            "version": "1.0.0",
                                            "colors": {
                                                "primary": {
                                                    "500": "#0047AB"
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
                "responses": {
                    "201": {
                        "description": "Branch created successfully",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/Branch"
                                }
                            }
                        }
                    },
                    "400": {
                        "description": "Invalid request - Branch ID already exists or invalid parameters",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/Error"
                                }
                            }
                        }
                    }
                }
            }
        },
        "/branches/{branchId}": {
            "get": {
                "summary": "Get branch details",
                "description": "Retrieve full details of a specific branch including its brand configuration",
                "operationId": "getBranch",
                "tags": ["Branches"],
                "parameters": [
                    {
                        "name": "branchId",
                        "in": "path",
                        "required": true,
                        "description": "Branch identifier in format owner/slug",
                        "schema": {
                            "type": "string",
                            "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*/[a-z0-9]+(?:-[a-z0-9]+)*$",
                            "example": "hdfc/retail"
                        }
                    }
                ],
                "responses": {
                    "200": {
                        "description": "Branch found",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/Branch"
                                }
                            }
                        }
                    },
                    "404": {
                        "description": "Branch not found",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/Error"
                                }
                            }
                        }
                    }
                }
            },
            "patch": {
                "summary": "Update branch",
                "description": "Update branch metadata or brand configuration. Updates the updatedAt timestamp automatically.",
                "operationId": "updateBranch",
                "tags": ["Branches"],
                "parameters": [
                    {
                        "name": "branchId",
                        "in": "path",
                        "required": true,
                        "schema": {
                            "type": "string"
                        }
                    }
                ],
                "requestBody": {
                    "required": true,
                    "content": {
                        "application/json": {
                            "schema": {
                                "$ref": "#/components/schemas/UpdateBranchRequest"
                            },
                            "example": {
                                "name": "HDFC Retail - Updated",
                                "description": "Updated description",
                                "brandConfig": {
                                    "brandId": "hdfc-retail",
                                    "name": "HDFC Retail",
                                    "colors": {
                                        "primary": {
                                            "500": "#0047AB"
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
                "responses": {
                    "200": {
                        "description": "Branch updated successfully"
                    },
                    "403": {
                        "description": "Forbidden - Branch is locked by another user"
                    }
                }
            }
        },
        "/branches/{branchId}/fork": {
            "post": {
                "summary": "Fork a branch",
                "description": "Create a copy of an existing branch with a reference to the original",
                "operationId": "forkBranch",
                "tags": ["Branches"],
                "parameters": [
                    {
                        "name": "branchId",
                        "in": "path",
                        "required": true,
                        "schema": {
                            "type": "string"
                        }
                    }
                ],
                "requestBody": {
                    "required": true,
                    "content": {
                        "application/json": {
                            "schema": {
                                "$ref": "#/components/schemas/ForkBranchRequest"
                            },
                            "example": {
                                "name": "HDFC Corporate",
                                "slug": "corporate"
                            }
                        }
                    }
                },
                "responses": {
                    "201": {
                        "description": "Branch forked successfully"
                    }
                }
            }
        },
        "/branches/{branchId}/versions": {
            "get": {
                "summary": "List versions",
                "description": "Get all published versions for a branch, ordered by publish date (newest first)",
                "operationId": "listVersions",
                "tags": ["Versions"],
                "parameters": [
                    {
                        "name": "branchId",
                        "in": "path",
