import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

/**
 * The root barrel is the package's semver commitment.
 *
 * Low-level internals — the CSS-string parsers, the surface resolver, the token
 * registry, the grouped-control helpers — must stay out of it. They exist to
 * serve the primitives, their shapes will change as more components land, and
 * `Block` / `Pressable` already expose everything a consumer needs to build a
 * token-driven surface.
 *
 * This reads the barrel rather than importing it, because importing pulls in
 * `react-native` and its Flow syntax cannot be parsed outside Metro.
 */

const barrel = readFileSync(resolve(__dirname, '../src/index.ts'), 'utf8')

/** Value exports only — `export type` lines are erased and cost nothing. */
function exportedValues(source: string): Set<string> {
    const names = new Set<string>()
    const blocks = source.matchAll(/export\s*\{([^}]*)\}/g)
    for (const block of blocks) {
        const start = block.index ?? 0
        // Skip `export type { ... }`.
        if (/export\s+type\s*\{$/.test(source.slice(0, start + 14).trim()))
            continue
        if (source.slice(start, start + 12).includes('type')) continue
        for (const entry of block[1].split(',')) {
            const name = entry
                .trim()
                .split(/\s+as\s+/)
                .pop()
                ?.trim()
            if (name) names.add(name)
        }
    }
    return names
}

const INTERNAL = [
    // CSS-string adapters — implementation detail of the primitives.
    'parseDimension',
    'parseSize',
    'parseBorder',
    'parseBorderRadius',
    'parseBoxShadow',
    'parseBackground',
    'resolveSurfaceStyle',
    'resolveBackground',
    // Token wiring.
    'NATIVE_TOKEN_REGISTRY',
    'NATIVE_TOKEN_SLOTS',
    'isNativeTokenSlot',
    // Helpers behind public behaviour.
    'resolveHitSlop',
    'sameHitSlop',
    'resolveBreakpoint',
    'tintSlot',
    'getGroupedBorderRadius',
    'getGroupedBorderWidths',
    'buildAnnouncement',
]

describe('public API surface', () => {
    const exported = exportedValues(barrel)

    it.each(INTERNAL)('does not export %s', (name) => {
        expect(exported.has(name)).toBe(false)
    })

    it('exports the components', () => {
        for (const name of [
            'Accordion',
            'Alert',
            'Avatar',
            'Badge',
            'Button',
            'Breadcrumb',
            'ButtonGroup',
            'Card',
            'Chart',
            'ChartContainer',
            'ChartHeader',
            'ChartLegend',
            'ChartNoData',
            'ChartSkeleton',
            'Checkbox',
            'IconButton',
            'OutageChart',
            'KeyValuePair',
            'LinkButton',
            'Menu',
            'MultiSelect',
            'NumberInput',
            'Popover',
            'OTPInput',
            'ProgressBar',
            'Radio',
            'SankeyChart',
            'SearchInput',
            'Sparkline',
            'SingleSelect',
            'Spinner',
            'StatCard',
            'Switch',
            'Tabs',
            'TextArea',
            'Tag',
            'TagGroup',
            'Tooltip',
            'Upload',
        ]) {
            expect(exported.has(name)).toBe(true)
        }
    })

    it('exports the theming entry points', () => {
        for (const name of [
            'BlendNativeProvider',
            'useNativeTokens',
            'useNativeBreakpoint',
        ]) {
            expect(exported.has(name)).toBe(true)
        }
    })

    it('exports the primitives for custom surfaces', () => {
        for (const name of ['Block', 'Pressable', 'Text', 'Slot']) {
            expect(exported.has(name)).toBe(true)
        }
    })

    it('stays small enough to review in one sitting', () => {
        // A guard against drift, not a hard architectural limit — if this
        // trips, decide deliberately whether the additions are public API.
        // Raised from 30 when the overlay foundation (Portal, BottomSheet,
        // useReduceMotion) became public, then to 40 for the field layer
        // (TextInput, PrimitiveInput, input enums) and the toast pair, then
        // to 44 for the Button/Tag family wave (IconButton, LinkButton,
        // ButtonGroup, TagGroup), then to 64 for the display wave (Spinner,
        // ProgressBar, Avatar, KeyValuePair, Card, Snackbar and their enums),
        // then to 84 for the Wave B form layer (Checkbox, Radio, Switch, the
        // compound Tabs/Accordion, the input variants, and their enums),
        // then to 85 when BottomSheetScrollable joined the sheet foundation
        // (Wave C0 scroll-aware drag), then to 96 for the Wave C1 overlay
        // components (Tooltip, Popover, Modal and their enums), then to 106
        // for Wave C2 (Menu, SingleSelect, MultiSelect and their enums),
        // then to 110 for Upload (+ validateUploadFiles, UploadState,
        // UploadErrorReason), then to 113 for Badge (+ BadgeColor,
        // BadgeSize), then to 122 for the chart wave (Chart and its
        // compounds, SankeyChart, OutageChart), then to 124 for the
        // select rework (select/menu enums and helpers), then to 125 for
        // Breadcrumb.
        expect(exported.size).toBeLessThanOrEqual(125)
    })
})

/**
 * Tests for API client — authentication, sanitization, retry logic.
 */
import { mkdtempSync, rmSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { beforeEach, afterEach, describe, it, expect, vi } from 'vitest'

async function createApiClient(apiUrl?: string) {
    // Re-evaluate module constants (AUTH_FILE based on homedir) after HOME changes.
    vi.resetModules()
    const mod = await import('../utils/api-client')
    return new mod.ApiClient(apiUrl)
}

describe('ApiClient', () => {
    const originalHome = process.env.HOME
    let tempHome = ''

    beforeEach(() => {
        tempHome = mkdtempSync(join(tmpdir(), 'blend-cli-test-home-'))
        process.env.HOME = tempHome
        delete process.env.BLEND_STUDIO_API_TOKEN
    })

    afterEach(() => {
        if (originalHome) {
            process.env.HOME = originalHome
        } else {
            delete process.env.HOME
        }
        rmSync(tempHome, { recursive: true, force: true })
    })

    it('creates instance with default API URL', async () => {
        const client = await createApiClient()
        expect(client).toBeTruthy()
    })

    it('creates instance with custom API URL', async () => {
        const client = await createApiClient('https://custom.api.com')
        expect(client).toBeTruthy()
    })

    it('is not authenticated by default (no auth file)', async () => {
        const client = await createApiClient('https://test.example.com')
        expect(client.isAuthenticated()).toBe(false)
    })

    it('getAuthEmail returns null when not authenticated', async () => {
        const client = await createApiClient('https://test.example.com')
        expect(client.getAuthEmail()).toBeNull()
    })

    it('clearAuth does not throw when no auth exists', async () => {
        const client = await createApiClient('https://test.example.com')
        expect(() => client.clearAuth()).not.toThrow()
    })
})

