import { render } from '@testing-library/react-native'
import { FOUNDATION_THEME, Theme } from '@juspay/blend-design-system/node'
import { BlendNativeProvider } from '../src/theme/BlendNativeProvider'
import { Text } from '../src/primitives/Text'
import { Tag } from '../src/components/Tag'

/**
 * Render coverage for the provider-level platform policies:
 *
 * - the font-family map reaching `Text` (RN's replacement for web's CSS
 *   font inheritance),
 * - `theme="system"` resolving against the OS appearance,
 * - the font-scaling policy (`minHeight`, scaling left ON).
 */

// `useColorScheme` reads internal Appearance state that spying on
// `Appearance.getColorScheme` does not reach — mock the hook's module, which
// `react-native`'s barrel re-exports. `jest.mock` is hoisted above imports.
const mockColorScheme = jest.fn<'light' | 'dark' | null, []>(() => 'light')
jest.mock('react-native/Libraries/Utilities/useColorScheme', () => ({
    __esModule: true,
    default: () => mockColorScheme(),
}))

const BODY_FAMILY = String(FOUNDATION_THEME.font.family.body)

const flatten = (style: unknown) =>
    Object.assign(
        {},
        ...(Array.isArray(style) ? style.flat(Infinity) : [style])
    )

describe('font family policy', () => {
    it('applies the token body family by default', () => {
        const { getByTestId } = render(
            <BlendNativeProvider>
                <Text testID="t">hello</Text>
            </BlendNativeProvider>
        )
        expect(flatten(getByTestId('t').props.style).fontFamily).toBe(
            BODY_FAMILY
        )
    })

    it('applies the family with no provider mounted (defaults)', () => {
        const { getByTestId } = render(<Text testID="t">hello</Text>)
        expect(flatten(getByTestId('t').props.style).fontFamily).toBe(
            BODY_FAMILY
        )
    })

    it("emits no family when the provider opts into 'system'", () => {
        const { getByTestId } = render(
            <BlendNativeProvider fontFamily="system">
                <Text testID="t">hello</Text>
            </BlendNativeProvider>
        )
        expect(flatten(getByTestId('t').props.style).fontFamily).toBeUndefined()
    })

    it('an explicit fontFamily prop wins over the map', () => {
        const { getByTestId } = render(
            <BlendNativeProvider>
                <Text testID="t" fontFamily="SpaceMono">
                    hello
                </Text>
            </BlendNativeProvider>
        )
        expect(flatten(getByTestId('t').props.style).fontFamily).toBe(
            'SpaceMono'
        )
    })

    it('components inherit the family through the provider', () => {
        const { getByText } = render(
            <BlendNativeProvider>
                <Tag text="Beta" />
            </BlendNativeProvider>
        )
        expect(flatten(getByText('Beta').props.style).fontFamily).toBe(
            BODY_FAMILY
        )
    })
})

describe('theme="system"', () => {
    afterEach(() => mockColorScheme.mockReturnValue('light'))

    /** A leaf whose value differs between the light and dark factories. */
    const probeTagBackground = (element: { props: { style?: unknown } }) =>
        flatten(element.props.style).backgroundColor

    it('resolves dark tokens when the OS is dark', () => {
        mockColorScheme.mockReturnValue('dark')
        const { getByTestId: q } = render(
            <BlendNativeProvider theme="system">
                <Tag text="Beta" testID="sys" />
            </BlendNativeProvider>
        )
        const { getByTestId: qDark } = render(
            <BlendNativeProvider theme={Theme.DARK}>
                <Tag text="Beta" testID="dark" />
            </BlendNativeProvider>
        )
        expect(probeTagBackground(q('sys'))).toBe(
            probeTagBackground(qDark('dark'))
        )
    })

    it('resolves light tokens when the OS is light', () => {
        mockColorScheme.mockReturnValue('light')
        const { getByTestId: q } = render(
            <BlendNativeProvider theme="system">
                <Tag text="Beta" testID="sys" />
            </BlendNativeProvider>
        )
        const { getByTestId: qLight } = render(
            <BlendNativeProvider theme={Theme.LIGHT}>
                <Tag text="Beta" testID="light" />
            </BlendNativeProvider>
        )
        expect(probeTagBackground(q('sys'))).toBe(
            probeTagBackground(qLight('light'))
        )
    })
})

describe('font scaling policy', () => {
    it('sizes Tag with minHeight, never a fixed height', () => {
        const { getByTestId } = render(
            <BlendNativeProvider>
                <Tag text="Beta" testID="tag" />
            </BlendNativeProvider>
        )
        const style = flatten(getByTestId('tag').props.style)
        expect(style.minHeight).toBeGreaterThan(0)
        expect(style.height).toBeUndefined()
    })

    it('leaves font scaling enabled on Text', () => {
        const { getByTestId } = render(<Text testID="t">hello</Text>)
        // RN's default is true; the policy is to not override it.
        expect(getByTestId('t').props.allowFontScaling).not.toBe(false)
    })
})

import React, { useMemo, useState } from 'react'
import { describe, it, expect } from 'vitest'
import { render, screen, waitFor } from '../../test-utils'
import DataTable from '../../../lib/components/DataTable/DataTable'
import {
    ColumnDefinition,
    ColumnType,
    SearchConfig,
} from '../../../lib/components/DataTable/types'

type Row = { id: number; name: string }

const columns: ColumnDefinition<Record<string, unknown>>[] = [
    { field: 'name', header: 'Name', type: ColumnType.TEXT, isSortable: false },
]

const DataTableServerSearchHarness = () => {
    // Same length and same first/last ids, but the middle id/name differs.
    const initialData = useMemo<Row[]>(
        () => [
            { id: 1, name: 'Alpha' },
            { id: 2, name: 'Beta' },
            { id: 3, name: 'Gamma' },
        ],
        []
    )
    const searchedData = useMemo<Row[]>(
        () => [
            { id: 1, name: 'Alpha' },
            { id: 99, name: 'Zeta' },
            { id: 3, name: 'Gamma' },
        ],
        []
    )

    const [data, setData] = useState<Row[]>(initialData)

    return (
        <DataTable
            title="Users"
            enableSearch
            serverSideSearch
            idField="id"
            columns={columns as unknown as ColumnDefinition<Row>[]}
            data={data}
            onSearchChange={(cfg: SearchConfig) => {
                setData(cfg.query.trim() ? searchedData : initialData)
            }}
        />
    )
}

describe('DataTable (server-side search)', () => {
    it('updates rendered rows when same-length results swap middle IDs', async () => {
        const { user } = render(<DataTableServerSearchHarness />)

        expect(screen.getByText('Alpha')).toBeInTheDocument()
        expect(screen.getByText('Beta')).toBeInTheDocument()
        expect(screen.getByText('Gamma')).toBeInTheDocument()

        const searchInput = screen.getByPlaceholderText('Search...')
        await user.type(searchInput, 'z')

        await waitFor(() => {
            expect(screen.getByText('Zeta')).toBeInTheDocument()
        })
        expect(screen.queryByText('Beta')).not.toBeInTheDocument()
    })
})

import React from 'react'
import { describe, expect, it, vi } from 'vitest'
import { render, screen } from '../../test-utils'
import { useSelectSearchController } from '../../../lib/components/Select/useSelectSearchController'

type HarnessProps = {
    controlledValue?: string
    onValueChange?: (value: string) => void
    explicitShow?: boolean
    existingSurfaceDefault?: boolean
}

const Harness = ({
    controlledValue,
    onValueChange,
    explicitShow,
    existingSurfaceDefault = false,
}: HarnessProps) => {
    const search = useSelectSearchController({
        controlledValue,
        onValueChange,
        explicitShow,
        existingSurfaceDefault,
    })

    return (
        <div>
            <output data-testid="value">{search.value}</output>
            <output data-testid="controlled">
                {String(search.isControlled)}
            </output>
            <output data-testid="enabled">
                {String(search.isSearchEnabled)}
            </output>
            <output data-testid="filters">
                {String(search.shouldFilterInternally)}
            </output>
            <button onClick={() => search.dispatchUserValue('next')}>
                Set
            </button>
            <button
                onClick={() =>
                    search.dispatchUserValue((previous) => `${previous}!`)
                }
            >
                Append
            </button>
            <button onClick={search.resetUncontrolled}>Reset</button>
        </div>
    )
}

describe('useSelectSearchController', () => {
    it('uses prop presence for controlled mode and never filters internally', async () => {
        const onValueChange = vi.fn()
        const { user } = render(
            <Harness controlledValue="" onValueChange={onValueChange} />
        )

        expect(screen.getByTestId('controlled')).toHaveTextContent('true')
        expect(screen.getByTestId('enabled')).toHaveTextContent('true')
        expect(screen.getByTestId('filters')).toHaveTextContent('false')

        await user.click(screen.getByRole('button', { name: 'Set' }))
        expect(onValueChange).toHaveBeenCalledWith('next')
        expect(screen.getByTestId('value')).toHaveTextContent('')
    })

    it('updates local state and optionally notifies in uncontrolled mode', async () => {
        const onValueChange = vi.fn()
        const { user } = render(<Harness onValueChange={onValueChange} />)

        expect(screen.getByTestId('filters')).toHaveTextContent('true')
        await user.click(screen.getByRole('button', { name: 'Set' }))
        expect(screen.getByTestId('value')).toHaveTextContent('next')
        expect(onValueChange).toHaveBeenCalledWith('next')

        await user.click(screen.getByRole('button', { name: 'Reset' }))
        expect(screen.getByTestId('value')).toHaveTextContent('')
        expect(onValueChange).toHaveBeenCalledTimes(1)
    })

    it('preserves existing defaults while explicit false wins', () => {
        const { rerender } = render(<Harness existingSurfaceDefault={true} />)
        expect(screen.getByTestId('enabled')).toHaveTextContent('true')

        rerender(<Harness controlledValue="query" explicitShow={false} />)
        expect(screen.getByTestId('controlled')).toHaveTextContent('true')
        expect(screen.getByTestId('enabled')).toHaveTextContent('false')
        expect(screen.getByTestId('filters')).toHaveTextContent('false')
    })

    it('supports functional user updates', async () => {
        const onValueChange = vi.fn()
        const { user } = render(<Harness onValueChange={onValueChange} />)

        await user.click(screen.getByRole('button', { name: 'Set' }))
        await user.click(screen.getByRole('button', { name: 'Append' }))

        expect(screen.getByTestId('value')).toHaveTextContent('next!')
        expect(onValueChange).toHaveBeenLastCalledWith('next!')
    })
})

