import type {
    Branch,
    Version,
    Snapshot,
    BrandConfig,
    CreateBranchInput,
    BranchListFilters,
    BranchListResult,
} from '@juspay/blend-design-system/tokens'
import {
    branches as MOCK_BRANCHES,
    versions as MOCK_VERSIONS,
    snapshots as MOCK_SNAPSHOTS,
} from './fixtures'

let branchCounter = MOCK_BRANCHES.length + 1

function delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms))
}

export const mockApi = {
    listBranches: async (
        filters?: BranchListFilters
    ): Promise<BranchListResult> => {
        await delay(500)
        let result = [...MOCK_BRANCHES]

        if (filters?.status)
            result = result.filter((b) => b.status === filters.status)
        if (filters?.search) {
            const q = filters.search.toLowerCase()
            result = result.filter(
                (b) =>
                    b.name.toLowerCase().includes(q) ||
                    b.id.toLowerCase().includes(q)
            )
        }
        if (filters?.tags?.length)
            result = result.filter((b) =>
                filters.tags!.some((tag) => b.tags?.includes(tag))
            )
        if (filters?.owner)
            result = result.filter((b) => b.createdBy === filters.owner)

        return { branches: result, total: result.length, hasMore: false }
    },

    getBranch: async (branchId: string): Promise<Branch | null> => {
        await delay(300)
        return MOCK_BRANCHES.find((b) => b.id === branchId) || null
    },

    createBranch: async (input: CreateBranchInput): Promise<Branch> => {
        await delay(800)
        const newBranch: Branch = {
            id: `${input.brandId}/${input.slug || `branch-${branchCounter}`}`,
            brandId: input.brandId,
            name: input.name,
            slug: input.slug || `branch-${branchCounter++}`,
            description: input.description || '',
            status: 'draft',
            visibility: input.visibility || 'private',
            brandConfig: (input.brandConfig as BrandConfig) || {
                brandId: input.brandId,
                name: input.name,
                version: '0.1.0',
                colors: {},
            },
            parentBranch: input.parentBranch || null,
            forkedFrom: input.forkFrom || null,
            owner: {
                uid: 'current-user',
                email: 'vinit.khandal@juspay.in',
                displayName: 'Vinit Khandal',
            },
            meta: {
                createdByName: 'Vinit Khandal',
                createdByEmail: 'vinit.khandal@juspay.in',
            },
            tags: input.tags || [],
            clientName: input.clientName,
            projectName: input.projectName,
            latestVersion: null,
            publishedCount: 0,
            snapshotCount: 0,
            createdBy: 'current-user',
            createdAt: new Date(),
            updatedAt: new Date(),
            lastEditedBy: 'current-user',
            lastPublishedAt: null,
            lastPublishedBy: null,
            isLocked: false,
            lockedBy: null,
            lockedAt: null,
        }
        MOCK_BRANCHES.push(newBranch)
        return newBranch
    },

    updateBranch: async (
        branchId: string,
        updates: {
            brandConfig?: BrandConfig
            name?: string
            description?: string
        }
    ): Promise<Branch> => {
        await delay(600)
        const branch = MOCK_BRANCHES.find((b) => b.id === branchId)
        if (!branch) throw new Error(`Branch ${branchId} not found`)
        if (updates.brandConfig) branch.brandConfig = updates.brandConfig
        if (updates.name !== undefined) branch.name = updates.name
        if (updates.description !== undefined)
            branch.description = updates.description
        branch.updatedAt = new Date()
        return branch
    },

    listVersions: async (branchId: string): Promise<Version[]> => {
        await delay(400)
        return MOCK_VERSIONS.get(branchId) || []
    },

    publishVersion: async (
        branchId: string,
        input: {
            version: string
            brandConfig: BrandConfig
            changelog?: string
            isBreaking?: boolean
            isPrerelease?: boolean
        }
    ): Promise<Version> => {
        await delay(1000)
        const branch = MOCK_BRANCHES.find((b) => b.id === branchId)
        if (!branch) throw new Error(`Branch ${branchId} not found`)

        const newVersion: Version = {
            id: input.version,
            branchId,
            version: input.version,
            brandConfig: input.brandConfig,
            changelog: input.changelog || '',
            isBreaking: input.isBreaking || false,
            isPrerelease: input.isPrerelease || false,
            publishedBy: 'current-user',
            publishedByName: 'Current User',
            publishedAt: new Date(),
            downloadCount: 0,
            lastDownloadedAt: null,
            parentVersion: branch.latestVersion,
        }

        const existing = MOCK_VERSIONS.get(branchId) || []
        existing.unshift(newVersion)
        MOCK_VERSIONS.set(branchId, existing)

        branch.latestVersion = input.version
        branch.publishedCount++
        branch.lastPublishedAt = new Date()
        branch.lastPublishedBy = 'current-user'
        branch.updatedAt = new Date()
        branch.status = 'published'

        return newVersion
    },

    listSnapshots: async (branchId: string): Promise<Snapshot[]> => {
        await delay(350)
        return MOCK_SNAPSHOTS.get(branchId) || []
    },

    deleteBranch: async (branchId: string): Promise<void> => {
        await delay(600)
        const idx = MOCK_BRANCHES.findIndex((b) => b.id === branchId)
        if (idx !== -1) MOCK_BRANCHES.splice(idx, 1)
    },

    forkBranch: async (
        sourceBranchId: string,
        newName: string,
        newSlug: string
    ): Promise<Branch> => {
        await delay(800)
        const source = MOCK_BRANCHES.find((b) => b.id === sourceBranchId)
        if (!source) throw new Error(`Branch ${sourceBranchId} not found`)
        const newBranch: Branch = {
            ...source,
            id: `${source.brandId}/${newSlug}`,
            slug: newSlug,
            name: newName,
            status: 'draft',
            latestVersion: null,
            publishedCount: 0,
            snapshotCount: 0,
            forkedFrom: { branchId: source.id, name: source.name },
            parentBranch: null,
            createdAt: new Date(),
            updatedAt: new Date(),
            lastPublishedAt: null,
            lastPublishedBy: null,
        }
        MOCK_BRANCHES.push(newBranch)
        return newBranch
    },

    createSnapshot: async (
        branchId: string,
        brandConfig: BrandConfig,
        label?: string,
        isAutoSave = true
    ): Promise<Snapshot> => {
        await delay(500)
        const snapshot: Snapshot = {
            id: `snapshot_${Date.now()}`,
            branchId,
            brandConfig,
            savedBy: 'current-user',
            savedByName: 'Current User',
            savedAt: new Date(),
            label: label || (isAutoSave ? 'Auto-saved' : 'Manual save'),
            isAutoSave,
        }
        const existing = MOCK_SNAPSHOTS.get(branchId) || []
        existing.unshift(snapshot)
        MOCK_SNAPSHOTS.set(branchId, existing)

        const branch = MOCK_BRANCHES.find((b) => b.id === branchId)
        if (branch) branch.snapshotCount = existing.length

        return snapshot
    },
}

import React from 'react'
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor, fireEvent } from '../../test-utils'
import userEvent from '@testing-library/user-event'
import Menu from '../../../lib/components/Menu/Menu'
import { getItemMatchRank } from '../../../lib/components/Menu/utils'
import type {
    MenuGroupType,
    MenuItemType,
} from '../../../lib/components/Menu/types'

const createBasicItems = (): MenuGroupType[] => [
    {
        items: [
            { label: 'Profile', onClick: vi.fn() },
            { label: 'Settings', onClick: vi.fn() },
            { label: 'Sign out', disabled: true },
        ],
    },
]

const createSearchItems = (): MenuGroupType[] => [
    {
        items: [{ label: 'Mostar' }, { label: 'Moscow' }, { label: 'Mumbai' }],
    },
]

const createRankedSearchItems = (): MenuGroupType[] => [
    {
        items: [
            { label: 'Advanced Search Tools', onClick: vi.fn() },
            { label: 'Search', onClick: vi.fn() },
            { label: 'Search Settings', onClick: vi.fn() },
        ],
    },
]

const createSubmenuSearchItems = (): MenuGroupType[] => [
    {
        items: [
            {
                label: 'United States',
                enableSubMenuSearch: true,
                subMenuSearchPlaceholder: 'Search states...',
                onSubMenuSearchEnter: vi.fn(),
                subMenu: [
                    { label: 'California', onClick: vi.fn() },
                    { label: 'New York', onClick: vi.fn() },
                    { label: 'Texas', onClick: vi.fn() },
                ],
            },
        ],
    },
]

describe('Menu search ranking & onEnter', () => {
    beforeEach(() => {
        global.ResizeObserver = class ResizeObserver {
            observe() {}
            unobserve() {}
            disconnect() {}
        } as unknown as typeof ResizeObserver
    })

    it('ranks search results so exact match appears before prefix and substring', async () => {
        const user = userEvent.setup()
        render(
            <Menu
                trigger={<button type="button">Ranked</button>}
                items={createRankedSearchItems()}
                enableSearch
                searchPlaceholder="Search..."
            />
        )

        await user.click(screen.getByRole('button', { name: /ranked/i }))
        const searchInput = await screen.findByPlaceholderText('Search...')
        await user.type(searchInput, 'search')

        await waitFor(() => {
            const items = screen.getAllByRole('menuitem')
            const texts = items.map((i) => i.textContent)
            const searchIdx = texts.findIndex((t) => t === 'Search')
            const prefixIdx = texts.findIndex((t) => t === 'Search Settings')
            const subIdx = texts.findIndex((t) => t === 'Advanced Search Tools')
            expect(searchIdx).toBeGreaterThanOrEqual(0)
            expect(searchIdx).toBeLessThan(prefixIdx)
            expect(prefixIdx).toBeLessThan(subIdx)
        })
    })

    it('calls onEnter with the current search text and filtered groups when Enter is pressed in the search input', async () => {
        const user = userEvent.setup()
        const onEnter = vi.fn()
        render(
            <Menu
                trigger={<button type="button">Enter</button>}
                items={createSearchItems()}
                enableSearch
                searchPlaceholder="Search cities..."
                onEnter={onEnter}
            />
        )

        await user.click(screen.getByRole('button', { name: /enter/i }))
        const searchInput =
            await screen.findByPlaceholderText('Search cities...')
        await user.type(searchInput, 'mos')
        await user.keyboard('{Enter}')

        await waitFor(() => {
            expect(onEnter).toHaveBeenCalledTimes(1)
        })
        const [query, filteredGroups] = onEnter.mock.calls[0]
        expect(query).toBe('mos')
        expect(filteredGroups.length).toBeGreaterThan(0)
        const matchedTexts = filteredGroups[0].items.map(
            (i: MenuItemType) => i.label
        )
        expect(matchedTexts).toContain('Moscow')
        expect(matchedTexts).toContain('Mostar')
    })

    it('does not call onEnter when enableSearch is false', async () => {
        const user = userEvent.setup()
        const onEnter = vi.fn()
        render(
            <Menu
                trigger={<button type="button">No search</button>}
                items={createBasicItems()}
                onEnter={onEnter}
            />
        )

        await user.click(screen.getByRole('button', { name: /no search/i }))
        await user.keyboard('{Enter}')
        expect(onEnter).not.toHaveBeenCalled()
    })

    it('honors a custom searchSortFn that overrides the default ranking', async () => {
        const user = userEvent.setup()
        // Reverse the default ranking: substring → prefix → exact
        const customSort = (items: MenuItemType[], searchText: string) => {
            const lower = searchText.toLowerCase()
            return [...items].sort(
                (a, b) =>
                    getItemMatchRank(b, lower) - getItemMatchRank(a, lower)
            )
        }
        render(
            <Menu
                trigger={<button type="button">Custom sort</button>}
                items={createRankedSearchItems()}
                enableSearch
                searchPlaceholder="Search..."
                searchSortFn={customSort}
            />
        )

        await user.click(screen.getByRole('button', { name: /custom sort/i }))
        const searchInput = await screen.findByPlaceholderText('Search...')
        await user.type(searchInput, 'search')

        await waitFor(() => {
            const items = screen.getAllByRole('menuitem')
            const texts = items.map((i) => i.textContent)
            // Reversed: substring first, exact last
            const searchIdx = texts.findIndex((t) => t === 'Search')
            const prefixIdx = texts.findIndex((t) => t === 'Search Settings')
            const subIdx = texts.findIndex((t) => t === 'Advanced Search Tools')
            expect(subIdx).toBeLessThan(prefixIdx)
            expect(prefixIdx).toBeLessThan(searchIdx)
        })
    })

    it('fires onSubMenuSearchEnter with query and filtered results when Enter is pressed in the sub-menu search input', async () => {
        const user = userEvent.setup()
        const items = createSubmenuSearchItems()
        const onSubMenuSearchEnter = items[0].items[0]
            .onSubMenuSearchEnter as ReturnType<typeof vi.fn>

        render(
            <Menu
                trigger={<button type="button">Submenu search</button>}
                items={items}
            />
        )

        await user.click(
            screen.getByRole('button', { name: /submenu search/i })
        )
        const parent = await screen.findByRole('menuitem', {
            name: /united states/i,
        })
        await user.click(parent)

        const subSearchInput =
            await screen.findByPlaceholderText('Search states...')
        fireEvent.change(subSearchInput, { target: { value: 'cal' } })
        fireEvent.keyDown(subSearchInput, { key: 'Enter', code: 'Enter' })

        await waitFor(() => {
            expect(onSubMenuSearchEnter).toHaveBeenCalledTimes(1)
        })
        const [query, filteredResults] = onSubMenuSearchEnter.mock.calls[0]
        expect(query).toBe('cal')
        expect(filteredResults.length).toBe(1)
        expect(filteredResults[0].label).toBe('California')
    })
})
